1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.time.LocalDate;
13	import java.time.Period;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public abstract class OwnerMapper {
22	
23	    /**
24	     * Points added when the owner has an email address.
25	     */
26	    private static final int EMAIL_POINTS = 2;
27	
28	    /**
29	     * Points added when the owner has no namesakes ({@code namesakeCount} is 0).
30	     */
31	    private static final int NO_NAMESAKE_POINTS = 1;
32	
33	    /**
34	     * Points added when the owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members.
35	     */
36	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
37	
38	    /**
39	     * The household size (members, including the owner) at which the large-household points are awarded.
40	     */
41	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
42	
43	    /**
44	     * Points added when the owner's tenure reaches {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
45	     */
46	    private static final int TENURE_POINTS = 3;
47	
48	    /**
49	     * Tenure, in elapsed fiscal years, that an owner must reach to earn the tenure points.
50	     */
51	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
52	
53	    /**
54	     * The month (1 July) on which the fiscal year starts.
55	     */
56	    private static final int FISCAL_YEAR_START_MONTH = 7;
57	
58	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
59	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
60	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
61	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
62	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + fiscalYearSuffix(owner.getRegistrationDate()))")
63	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
64	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
65	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
66	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.of(owner.getCity(), owner.getPostcode()))")
67	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.timezoneOf(owner.getCity(), owner.getPostcode()))")
68	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
69	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
70	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
71	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
72	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
73	    public abstract OwnerDto toOwnerDto(Owner owner);
74	
75	    public abstract Owner toOwner(OwnerDto ownerDto);
76	
77	    @Mapping(target = "id", ignore = true)
78	    @Mapping(target = "pets", ignore = true)
79	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
80	
81	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
82	
83	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
84	
85	    /**
86	     * Computes an owner's membership points. Points start at 0 and accumulate: {@value #EMAIL_POINTS} when an
87	     * email is present, {@value #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
88	     * {@value #LARGE_HOUSEHOLD_POINTS} for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members, and
89	     * {@value #TENURE_POINTS} for a tenure of at least {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal
90	     * year(s) (measured from {@code registrationDate}). Because a newly created owner has zero elapsed fiscal
91	     * years, a new owner never earns the tenure points.
92	     *
93	     * @param owner the owner whose points are being computed
94	     * @return the owner's membership points (0 or more)
95	     */
96	    protected Integer membershipPoints(Owner owner) {
97	        int points = 0;
98	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
99	            points += EMAIL_POINTS;
100	        }
101	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
102	            points += NO_NAMESAKE_POINTS;
103	        }
104	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_SIZE) {
105	            points += LARGE_HOUSEHOLD_POINTS;
106	        }
107	        if (tenureFiscalYears(owner) >= TENURE_POINTS_FISCAL_YEARS) {
108	            points += TENURE_POINTS;
109	        }
110	        return points;
111	    }
112	
113	    /**
114	     * Maps an owner's membership points to a numeric membership level: level 1 for 0-1 points, level 2 for
115	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
116	     *
117	     * @param owner the owner whose level is being computed
118	     * @return the membership level (between 1 and 4 inclusive)
119	     */
120	    protected Integer membershipLevel(Owner owner) {
121	        int points = membershipPoints(owner);
122	        if (points >= 6) {
123	            return 4;
124	        }
125	        if (points >= 4) {
126	            return 3;
127	        }
128	        if (points >= 2) {
129	            return 2;
130	        }
131	        return 1;
132	    }
133	
134	    /**
135	     * Computes an owner's tenure as the number of elapsed fiscal years between {@code registrationDate} and
136	     * today: the difference between the fiscal year (starting 1 July) of today and that of the registration
137	     * date. A newly created owner (registered in the current fiscal year) has zero tenure. Owners with no
138	     * {@code registrationDate}, or a registration date in a later fiscal year, are treated as zero tenure.
139	     *
140	     * @param owner the owner whose tenure is being computed
141	     * @return the owner's tenure in elapsed fiscal years, never negative
142	     */
143	    protected long tenureFiscalYears(Owner owner) {
144	        LocalDate registrationDate = owner.getRegistrationDate();
145	        if (registrationDate == null) {
146	            return 0;
147	        }
148	        long years = (long) fiscalYearStart(LocalDate.now()) - fiscalYearStart(registrationDate);
149	        return Math.max(years, 0);
150	    }
151	
152	    /**
153	     * Derives an owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, from the (already
154	     * business-day-adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is labelled by
155	     * the calendar year in which it starts, so a registration on or after 1 July belongs to that year's
156	     * fiscal year and an earlier one to the previous year's (e.g. {@code 2026-08-15} yields {@code 'FY26'}).
157	     *
158	     * @param owner the owner whose fiscal year is being derived
159	     * @return the owner's fiscal year as {@code 'FY<YY>'}
160	     */
161	    protected String fiscalYear(Owner owner) {
162	        return "FY" + fiscalYearSuffix(owner.getRegistrationDate());
163	    }
164	
165	    /**
166	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
167	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the shared segment
168	     * used by both {@link #fiscalYear(Owner)} and the membership number.
169	     *
170	     * @param date the date whose fiscal-year suffix is computed
171	     * @return the zero-padded two-digit fiscal-year suffix
172	     */
173	    protected String fiscalYearSuffix(LocalDate date) {
174	        return String.format("%02d", fiscalYearStart(date) % 100);
175	    }
176	
177	    /**
178	     * Returns the calendar year in which the fiscal year containing {@code date} starts. The fiscal year
179	     * starts on 1 July, so dates from July onward start their fiscal year in the same calendar year, while
180	     * dates from January to June belong to the fiscal year that started in the previous calendar year.
181	     *
182	     * @param date the date whose fiscal-year start is computed
183	     * @return the calendar year in which the containing fiscal year starts
184	     */
185	    protected int fiscalYearStart(LocalDate date) {
186	        int year = date.getYear();
187	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year : year - 1;
188	    }
189	
190	    /**
191	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits contained in
192	     * the owner's {@code customerCode}. Non-digit characters (such as the letters and dashes in the code) are
193	     * skipped; the rightmost digit is doubled and every second digit thereafter, digits exceeding 9 after
194	     * doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
195	     *
196	     * @param owner the owner whose check digit is being computed
197	     * @return the Luhn check digit (between 0 and 9 inclusive) over the customer code's digits
198	     */
199	    protected Integer checkDigit(Owner owner) {
200	        String code = owner.getCustomerCode() == null ? "" : owner.getCustomerCode();
201	        int sum = 0;
202	        boolean dbl = true;
203	        for (int i = code.length() - 1; i >= 0; i--) {
204	            char c = code.charAt(i);
205	            if (c < '0' || c > '9') {
206	                continue;
207	            }
208	            int d = c - '0';
209	            if (dbl) {
210	                d *= 2;
211	                if (d > 9) {
212	                    d -= 9;
213	                }
214	            }
215	            sum += d;
216	            dbl = !dbl;
217	        }
218	        return (10 - (sum % 10)) % 10;
219	    }
220	
221	    /**
222	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
223	     * present, otherwise {@code 'PHONE'}.
224	     *
225	     * @param owner the owner whose contact preference is being computed
226	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
227	     */
228	    protected String contactPreference(Owner owner) {
229	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
230	    }
231	
232	    /**
233	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
234	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
235	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
236	     * {@code birthDate}, so the field is simply absent for owners created without one.
237	     *
238	     * @param owner the owner whose age band is being derived
239	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
240	     */
241	    protected String ageBand(Owner owner) {
242	        if (owner.getBirthDate() == null) {
243	            return null;
244	        }
245	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
246	        int years = Period.between(owner.getBirthDate(), reference).getYears();
247	        if (years < 18) {
248	            return "MINOR";
249	        }
250	        if (years < 65) {
251	            return "ADULT";
252	        }
253	        return "SENIOR";
254	    }
255	
256	    /**
257	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
258	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
259	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'}). This is the single key used for duplicate detection,
260	     * so the value returned here matches the one the create endpoint compares.
261	     *
262	     * @param owner the owner whose identity key is being derived
263	     * @return the owner's identity key
264	     */
265	    protected String identityKey(Owner owner) {
266	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
267	        String email = owner.getEmail() == null ? "" : owner.getEmail();
268	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
269	        return telephone + "|" + email + "|" + householdId;
270	    }
271	
272	    /**
273	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
274	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
275	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
276	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
277	     * <p>
278	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
279	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
280	     *
281	     * @param owner the owner whose telephone is being formatted
282	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
283	     */
284	    protected String telephoneDisplay(Owner owner) {
285	        String telephone = owner.getTelephone();
286	        if (telephone == null || !telephone.startsWith("+")) {
287	            return telephone;
288	        }
289	        String digits = telephone.substring(1);
290	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
291	        if (digits.length() <= countryCodeLength) {
292	            return telephone;
293	        }
294	        String countryCode = digits.substring(0, countryCodeLength);
295	        String national = digits.substring(countryCodeLength);
296	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
297	        for (int i = 0; i < national.length(); i++) {
298	            if (i % 3 == 0) {
299	                grouped.append(' ');
300	            }
301	            grouped.append(national.charAt(i));
302	        }
303	        return grouped.toString();
304	    }
305	
306	    /**
307	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
308	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
309	     * title was given.
310	     *
311	     * @param owner the owner whose salutation is being composed
312	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
313	     */
314	    protected String salutation(Owner owner) {
315	        String title = owner.getTitle();
316	        if (title == null || title.isBlank()) {
317	            return owner.getLastName();
318	        }
319	        return title + " " + owner.getLastName();
320	    }
321	
322	    /**
323	     * Derives an owner's {@code selfLink}: the canonical relative URL of the owner resource, formatted
324	     * {@code '/api/owners/<id>'} from the owner's id. Returns {@code null} when the owner has no id yet.
325	     *
326	     * @param owner the owner whose self link is being derived
327	     * @return the owner's self link, or {@code null} when the owner has no id
328	     */
329	    protected String selfLink(Owner owner) {
330	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
331	    }
332	
333	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
334	        OwnerPageDto ownerPageDto = new OwnerPageDto();
335	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
336	        ownerPageDto.setPage(ownerPage.getNumber());
337	        ownerPageDto.setSize(ownerPage.getSize());
338	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
339	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
