162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        String idempotencyKey = idempotencyKey();
166	        if (idempotencyKey != null) {
167	            Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
168	            if (existingId != null) {
169	                Owner existing = this.clinicService.findOwnerById(existingId);
170	                if (existing != null) {
171	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
172	                }
173	            }
174	        }
175	        rejectMissingOrBlankFields(ownerFieldsDto);
176	        HttpHeaders headers = new HttpHeaders();
177	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
178	        applyAddress(owner);
179	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
180	        owner.setEmail(normalizeEmail(owner.getEmail()));
181	        validatePostcode(owner.getPostcode(), owner.getCity());
182	        rejectFutureRegistrationDate(owner.getRegistrationDate());
183	        if (owner.getRegistrationDate() == null) {
184	            owner.setRegistrationDate(LocalDate.now());
185	        }
186	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
187	        rejectDailyLimitReached(owner.getRegistrationDate());
188	        rejectCityAtCapacity(owner.getCity());
189	        owner.setHouseholdId(computeHouseholdId(owner));
190	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
191	        rejectDuplicateIdentity(owner);
192	        if (!sharesHousehold) {
193	            rejectHouseholdDuplicate(owner);
194	        }
195	        assignPossibleDuplicate(owner, sharesHousehold);
196	        owner.setCustomerCode(generateCustomerCode(owner));
197	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
198	        owner.setHouseholdSize(countHouseholdSize(owner.getHouseholdId()));
199	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
200	        this.clinicService.saveOwner(owner);
201	        if (idempotencyKey != null) {
202	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
203	        }
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
206	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
207	            ownerDto.getMembershipNumber());
208	        headers.setLocation(UriComponentsBuilder.newInstance()
209	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
210	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
211	    }
