308	    /**
309	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
310	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
311	     *
312	     * @param fields the submitted owner fields
313	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
314	     *                                        {@code null} or blank, or if the owner supplies no address
315	     *                                        in either form (a blank structured {@code addressLine1} and a
316	     *                                        blank flat {@code address}, each measured after normalization)
317	     */
318	    /**
319	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
320	     *
321	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
322	     */
323	    private String idempotencyKey() {
324	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
325	        if (key == null || key.isBlank()) {
326	            return null;
327	        }
328	        return key.strip();
329	    }
