331	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
332	        List<String> missing = new ArrayList<>();
333	        if (isBlank(fields.getFirstName())) {
334	            missing.add("firstName");
335	        }
336	        if (isBlank(fields.getLastName())) {
337	            missing.add("lastName");
338	        }
339	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
340	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
341	        if (!hasStructuredAddress && !hasFlatAddress) {
342	            missing.add("address");
343	        }
344	        if (isBlank(fields.getCity())) {
345	            missing.add("city");
346	        }
347	        if (isBlank(fields.getTelephone())) {
348	            missing.add("telephone");
349	        }
350	        if (!missing.isEmpty()) {
351	            throw new RequiredFieldsMissingException(missing);
352	        }
353	    }
