359	    /**
360	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
361	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
362	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
363	     */
364	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
365	        "NSW", new int[] {2000, 2099},
366	        "VIC", new int[] {3000, 3099},
367	        "QLD", new int[] {4000, 4099});
368	
369	    /**
370	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
371	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
372	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
373	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
374	     *
375	     * @param postcode the submitted postcode, or {@code null} when omitted
376	     * @param city the owner's city, used to derive the region whose range constrains the postcode
377	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
378	     *                                  city's region
379	     */
380	    private void validatePostcode(String postcode, String city) {
381	        if (postcode == null) {
382	            return;
383	        }
384	        if (!postcode.matches("[0-9]{4}")) {
385	            throw new InvalidPostcodeException(postcode);
386	        }
387	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
388	        if (range == null) {
389	            return;
390	        }
391	        int value = Integer.parseInt(postcode);
392	        if (value < range[0] || value > range[1]) {
393	            throw new InvalidPostcodeException(postcode);
394	        }
395	    }
