397	    /**
398	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
399	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
400	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
401	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
402	     * <p>
403	     * Where a per-country rule is defined the national-number length is validated against the country
404	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
405	     * requires exactly 10.
406	     *
407	     * @param telephone the raw telephone value from the request
408	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
409	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
410	     */
411	    private String normalizeTelephone(String telephone) {
412	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
413	        String digits;
414	        if (cleaned.startsWith("+")) {
415	            digits = cleaned.substring(1);
416	        } else {
417	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
418	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
419	            digits = "61" + national;
420	        }
421	        if (!digits.matches("[0-9]{8,15}")) {
422	            throw new InvalidTelephoneException(cleaned);
423	        }
424	        // Validate the national-number length against the country code where a rule is defined.
425	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
426	            throw new InvalidTelephoneException(cleaned);
427	        }
428	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
429	            throw new InvalidTelephoneException(cleaned);
430	        }
431	        return "+" + digits;
432	    }
