434	    /**
435	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
436	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
437	     * lower-cased.
438	     *
439	     * @param email the raw email value from the request, or {@code null} if omitted
440	     * @return the lower-cased email, or {@code null} if none was supplied
441	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
442	     */
443	    private String normalizeEmail(String email) {
444	        if (email == null) {
445	            return null;
446	        }
447	        String trimmed = email.strip();
448	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
449	            throw new InvalidEmailException(email);
450	        }
451	        String normalized = trimmed.toLowerCase(Locale.ROOT);
452	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
453	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
454	            throw new DisposableEmailDomainException(domain);
455	        }
456	        return normalized;
457	    }
