459	    /**
460	     * Applies the owner's address in whichever form the request supplied, preferring the structured
461	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
462	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
463	     * value: the normalized {@code addressLine1}, with a single space and the normalized
464	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
465	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
466	     * flat-address contract backward-compatible.
467	     *
468	     * @param owner the owner being created, mapped straight from the request
469	     */
470	    private void applyAddress(Owner owner) {
471	        if (!isBlank(owner.getAddressLine1())) {
472	            String line1 = normalizeAddress(owner.getAddressLine1());
473	            owner.setAddressLine1(line1);
474	            String composed = line1;
475	            if (!isBlank(owner.getAddressLine2())) {
476	                String line2 = normalizeAddress(owner.getAddressLine2());
477	                owner.setAddressLine2(line2);
478	                composed = line1 + " " + line2;
479	            } else {
480	                owner.setAddressLine2(null);
481	            }
482	            owner.setAddress(composed);
483	        } else {
484	            owner.setAddressLine1(null);
485	            owner.setAddressLine2(null);
486	            owner.setAddress(normalizeAddress(owner.getAddress()));
487	        }
488	    }
489	
490	    /**
491	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
492	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
493	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
494	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
495	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
496	     *
497	     * @param address the raw address value from the request (may be {@code null})
498	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
499	     */
500	    private String normalizeAddress(String address) {
501	        if (address == null) {
502	            return "";
503	        }
504	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
505	        if (collapsed.isEmpty()) {
506	            return "";
507	        }
508	        String[] tokens = collapsed.split(" ");
509	        StringBuilder sb = new StringBuilder(collapsed.length());
510	        for (int i = 0; i < tokens.length; i++) {
511	            if (i > 0) {
512	                sb.append(' ');
513	            }
514	            sb.append(expandAddressAbbreviation(tokens[i]));
515	        }
516	        return sb.toString();
517	    }
518	
519	    /**
520	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
521	     * returns the token unchanged when it is not a recognised abbreviation.
522	     *
523	     * @param token an upper-cased whole-word address token
524	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
525	     */
526	    private String expandAddressAbbreviation(String token) {
527	        return switch (token) {
528	            case "ST" -> "STREET";
529	            case "RD" -> "ROAD";
530	            case "AVE" -> "AVENUE";
531	            default -> token;
532	        };
533	    }
534	
535	    /**
536	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
537	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
538	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
539	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
540	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}).
541	     * <p>
542	     * Should the computed code collide with an existing owner's {@code customerCode}, it is de-duplicated
543	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
544	     * held by any existing owner; the de-duplicated code is returned.
545	     *
546	     * @param owner the owner being created, with normalized telephone and postcode already set
547	     * @return the assigned, collision-free customer code
548	     */
549	    private String generateCustomerCode(Owner owner) {
550	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
551	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
552	            .substring(0, 8).toUpperCase(Locale.ROOT);
553	        String base = region + "-" + hash8;
554	        Set<String> existing = this.clinicService.findAllOwners().stream()
555	            .map(Owner::getCustomerCode)
556	            .filter(code -> code != null)
557	            .collect(java.util.stream.Collectors.toSet());
558	        if (!existing.contains(base)) {
559	            return base;
560	        }
561	        int n = 2;
562	        while (existing.contains(base + "-" + n)) {
563	            n++;
564	        }
565	        return base + "-" + n;
566	    }
567	
568	    /**
569	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
570	     *
571	     * @param value the value to hash
572	     * @return the 64-character lower-case hex SHA-256 digest
573	     */
574	    private String sha256Hex(String value) {
575	        try {
576	            byte[] digest = MessageDigest.getInstance("SHA-256")
577	                .digest(value.getBytes(StandardCharsets.UTF_8));
578	            StringBuilder sb = new StringBuilder(digest.length * 2);
579	            for (byte b : digest) {
580	                sb.append(String.format("%02x", b));
581	            }
582	            return sb.toString();
583	        } catch (NoSuchAlgorithmException e) {
584	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
585	        }
586	    }
587	
588	    /**
589	     * Counts how many existing owners already share the given first name and last name, compared
590	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
591	     * owner being created.
592	     *
593	     * @param firstName the first name of the owner being created
594	     * @param lastName the last name of the owner being created
595	     * @return the number of existing owners with the same first and last name (case-insensitively)
596	     */
597	    private int countNamesakes(String firstName, String lastName) {
598	        return (int) this.clinicService.findAllOwners().stream()
599	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
600	                && lastName.equalsIgnoreCase(existing.getLastName()))
601	            .count();
602	    }
603	
604	    /**
605	     * Computes the size of the owner's household: the number of existing owners already sharing the given
606	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
607	     * owner is persisted, so adding one for the owner yields the household's total membership including it
608	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
609	     * the deterministic {@code householdId} (derived from last name and postcode).
610	     *
611	     * @param householdId the computed household identifier of the owner being created
612	     * @return the household size including the owner being created (at least 1)
613	     */
614	    private int countHouseholdSize(String householdId) {
615	        long existing = this.clinicService.findAllOwners().stream()
616	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
617	            .count();
618	        return (int) existing + 1;
619	    }
620	
621	    /**
622	     * The maximum number of owners permitted in a single city. A create request whose city already
623	     * holds this many owners is rejected.
624	     */
625	    private static final int CITY_OWNER_LIMIT = 50;
626	
627	    /**
628	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
629	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
630	     * differing only in the casing of their city share one capacity pool. The count is taken before the
631	     * new owner is persisted, so it excludes the owner being created.
632	     *
633	     * @param city the city of the owner being created
634	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
635	     */
636	    private void rejectCityAtCapacity(String city) {
637	        long existing = this.clinicService.findAllOwners().stream()
638	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
639	            .count();
640	        if (existing >= CITY_OWNER_LIMIT) {
641	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
642	        }
643	    }
644	
645	    /**
646	     * The maximum number of owners permitted to be created in a single day. A create request whose
647	     * registration date already holds this many owners is rejected.
648	     */
649	    private static final int DAILY_OWNER_LIMIT = 100;
650	
651	    /**
652	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
653	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
654	     * persisted, so it excludes the owner being created.
655	     *
656	     * @param registrationDate the registration date of the owner being created
657	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
658	     */
659	    /**
660	     * The fixed list of public holidays that are not treated as business days. A registration date that
661	     * lands on one of these dates is rolled forward, just as a weekend is.
662	     */
663	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
664	        LocalDate.of(2026, 1, 1),
665	        LocalDate.of(2026, 1, 26),
666	        LocalDate.of(2026, 4, 25),
667	        LocalDate.of(2026, 12, 25),
668	        LocalDate.of(2026, 12, 28));
669	
670	    /**
671	     * Adjusts an effective registration date so that it always falls on a business day. When the given
672	     * date is a Saturday, a Sunday or a listed public holiday it is rolled forward one day at a time until
673	     * it reaches the next non-holiday business day; a weekday that is not a holiday is returned unchanged.
674	     * This applies equally to a date supplied in the request and to a date defaulted to the server date, and
675	     * the adjusted value is what becomes the owner's {@code registrationDate}, so every value derived from it
676	     * (the membership number's year segment, the daily create-limit count) uses the business-day-adjusted
677	     * date.
678	     *
679	     * @param date the effective registration date, supplied or defaulted
680	     * @return the same date when it is a business day, otherwise the next non-holiday business day
681	     */
682	    private LocalDate rollToBusinessDay(LocalDate date) {
683	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
684	            date = date.plusDays(1);
685	        }
686	        return date;
687	    }
688	
689	    private boolean isWeekend(LocalDate date) {
690	        DayOfWeek day = date.getDayOfWeek();
691	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
692	    }
693	
694	    /**
695	     * The number of owners that must already exist for a given day before a further create is flagged as a
696	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
697	     * the created owner carries {@code bulkSignupWarning = true}.
698	     */
699	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
700	
701	    /**
702	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
703	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
704	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
705	     * the daily create-limit rule's accumulation path.
706	     *
707	     * @param registrationDate the registration date of the owner being created
708	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
709	     */
710	    private boolean isBulkSignupDay(LocalDate registrationDate) {
711	        long existing = this.clinicService.findAllOwners().stream()
712	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
713	            .count();
714	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
715	    }
716	
717	    /**
718	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
719	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
720	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
721	     * made against the supplied value before any business-day adjustment.
722	     *
723	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
724	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
725	     */
726	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
727	        if (registrationDate == null) {
728	            return;
729	        }
730	        LocalDate today = LocalDate.now();
731	        if (registrationDate.isAfter(today)) {
732	            throw new FutureRegistrationDateException(registrationDate, today);
733	        }
734	    }
735	
736	    private void rejectDailyLimitReached(LocalDate registrationDate) {
737	        long existing = this.clinicService.findAllOwners().stream()
738	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
739	            .count();
740	        if (existing >= DAILY_OWNER_LIMIT) {
741	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
742	        }
743	    }
744	
745	    /**
746	     * Rejects a create request whose owner collides with an existing owner on the single derived
747	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
748	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
749	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
750	     * household (same {@code householdId}) with different telephones have different keys and are both
751	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
752	     * been computed (deterministically from the last name and postcode) before this check runs, so the
753	     * key compared here is the same one that is later returned.
754	     *
755	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
756	     * @throws DuplicateIdentityException if an existing owner has the same identity key
757	     */
758	    private void rejectDuplicateIdentity(Owner owner) {
759	        String key = identityKey(owner);
760	        boolean taken = this.clinicService.findAllOwners().stream()
761	            .filter(existing -> !isDeleted(existing))
762	            .anyMatch(existing -> key.equals(identityKey(existing)));
763	        if (taken) {
764	            throw new DuplicateIdentityException(key);
765	        }
766	    }
767	
768	    /**
769	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
770	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
771	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
772	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
773	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
774	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
775	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
776	     * <p>
777	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
778	     * postcode is now exactly the household key, so such an owner is a known household member rather than
779	     * a suspected duplicate.
780	     *
781	     * @param owner the owner being created, with normalized telephone and validated postcode already set
782	     * @param sharesHousehold whether the create declared the owner a household member
783	     */
784	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
785	        Integer matchId = null;
786	        if (!sharesHousehold && owner.getPostcode() != null) {
787	            matchId = this.clinicService.findAllOwners().stream()
788	                .filter(existing -> !isDeleted(existing))
789	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
790	                    && owner.getPostcode().equals(existing.getPostcode())
791	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
792	                .map(Owner::getId)
793	                .filter(id -> id != null)
794	                .min(Comparator.naturalOrder())
795	                .orElse(null);
796	        }
797	        owner.setPossibleDuplicate(matchId != null);
798	        owner.setPossibleDuplicateOf(matchId);
799	    }
800	
801	    private boolean telephonesEqual(String a, String b) {
802	        return a == null ? b == null : a.equals(b);
803	    }
804	
805	    /**
806	     * Whether an existing owner has been soft-deleted. A soft-deleted owner is retained and still
807	     * readable, but is ignored by the create endpoint's duplicate and identity checks.
808	     *
809	     * @param owner an existing owner
810	     * @return {@code true} when the owner is flagged deleted, otherwise {@code false}
811	     */
812	    private boolean isDeleted(Owner owner) {
813	        return Boolean.TRUE.equals(owner.getDeleted());
814	    }
815	
816	    /**
817	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
818	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
819	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
820	     * Telephone and email are stored already normalized, so the stored values are used directly.
821	     *
822	     * @param owner the owner whose identity key is being derived
823	     * @return the owner's identity key
824	     */
825	    private String identityKey(Owner owner) {
826	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
827	        String email = owner.getEmail() == null ? "" : owner.getEmail();
828	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
829	        return telephone + "|" + email + "|" + householdId;
830	    }
831	
832	    /**
833	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
834	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
835	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
836	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
837	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
838	     * whether or not {@code sharesHousehold} was requested.
839	     *
840	     * @param owner the owner being created, with its validated postcode already set
841	     * @return the deterministic household identifier
842	     */
843	    private String computeHouseholdId(Owner owner) {
844	        String normalizedLastName = normalizeForComparison(owner.getLastName());
845	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
846	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
847	    }
848	
849	    /**
850	     * Rejects a create request whose owner would join an existing household without declaring it. The
851	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
852	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
853	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
854	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
855	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
856	     *
857	     * @param owner the owner being created, with its computed {@code householdId} already assigned
858	     * @throws HouseholdDuplicateException if an existing owner already shares the household
859	     */
860	    private void rejectHouseholdDuplicate(Owner owner) {
861	        String householdId = owner.getHouseholdId();
862	        boolean shared = this.clinicService.findAllOwners().stream()
863	            .filter(existing -> !isDeleted(existing))
864	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
865	        if (shared) {
866	            throw new HouseholdDuplicateException(householdId);
867	        }
868	    }
869	
870	    /**
871	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
872	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
873	     * lower-cased.
874	     *
875	     * @param value the raw value to normalize (may be {@code null})
876	     * @return the normalized value, or an empty string when {@code value} is {@code null}
877	     */
878	    private String normalizeForComparison(String value) {
879	        if (value == null) {
880	            return "";
881	        }
882	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
883	    }
884	}
